const items = $input.all();
const out = [];
for (const it of items) {
  let raw = it.json?.body || it.json || {};
  let body = raw;
  if (raw.entry && Array.isArray(raw.entry)) {
    for (const entry of raw.entry) {
      for (const change of (entry.changes || [])) {
        if (change.field === 'messages' && change.value) { body = change.value; break; }
      }
    }
  }
  if (body.statuses && !body.messages) continue;
  if (!body.messages || body.messages.length === 0) continue;
  for (const msg of body.messages) {
    if (msg.type !== 'text' || !msg.text?.body) continue;
    const rawText = msg.text.body.trim();
    if (!rawText) continue;
    const phone = msg.from;
    const contact = (body.contacts||[]).find(c => c.wa_id === phone) || {};
    const bnChars = (rawText.match(/[\u0980-\u09FF]/g)||[]).length;
    const hiChars = (rawText.match(/[\u0900-\u097F]/g)||[]).length;
    const enWords = (rawText.match(/[a-zA-Z]{3,}/g)||[]).length;
    let lang = 'bn';
    if (bnChars >= 2) lang = 'bn';
    else if (hiChars >= 3) lang = 'hi';
    else if (enWords >= 3 && !bnChars && !hiChars) lang = 'en';
    const ticketMatch = rawText.match(/WB-\d{2}-[A-Z]{3}-\d{6}/i);
    out.push({ json: { phone, text: rawText, waName: contact.profile?.name || null, messageId: msg.id, language: lang, ticketInText: ticketMatch ? ticketMatch[0].toUpperCase() : null, isRatingOnly: /^[1-5]$/.test(rawText), receivedAt: new Date().toISOString() }});
  }
}
return out;

const ctx = $('Parse Message').first().json;
const sess = $('Upsert Session').first().json;
const sessRow = Array.isArray(sess) ? (sess[0]||{}) : (sess||{});
const collected = sessRow.collected_data || {};
const lang = ctx.language || 'bn';
const dn = {'puruliya':'Purulia','howra':'Howrah','burdwan':'Purba Bardhaman','maldah':'Malda','nadiya':'Nadia'};
const bn = {'manbazar-1':'Manbazar I','manbazar1':'Manbazar I','manbazar 1':'Manbazar I','manbazar-2':'Manbazar II','manbazar2':'Manbazar II','manbazar 2':'Manbazar II'};
if (collected.district) { const k=collected.district.toLowerCase().trim(); if(dn[k]) collected.district=dn[k]; }
if (collected.block) { const k=collected.block.toLowerCase().trim(); if(bn[k]) collected.block=bn[k]; }
return [{ json: { ...ctx, language: lang, prior_state: sessRow.state || 'idle', prior_collected: collected, prior_intent: sessRow.last_intent || null } }];
